<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserProviderVO;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserProviderAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProviderAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProviderAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getProvider returns null on a freshly created holder.
         */
        public function testProviderNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserProviderAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isProviderAssigned());
            $this->assertNull($holder->getProvider());
        }
}
class ImplWithUserProviderAttributeHolderUnitTest
{
  use UserProviderAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedProviderRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultProvider();
    }}
